    MOV VY,P1
    MOV P0,P0
    SWRITE P0
    ; Pxl-On
    ; Load X into P0
    MOV P0,[0x2002]
    MOV P1,3
    ADD P0,P1
    ; Load Y into P1
    MOV P1,[0x2000]
    MOV P2,236
    ; Pxl-On at (P0,P1)
    MOV VX,P0
    MOV VY,P1
    MOV P0,P2
    SWRITE P0
    ; Y = 
    ; Load Y into P2
    MOV P2,[0x2000]
    MOV P1,1
    ADD P2,P1
    ; Store P2 into Y
    MOV [0x2000],P2
    ; Pxl-On
    ; Load X into P2
    MOV P2,[0x2002]
    ; Load Y into P1
    MOV P1,[0x2000]
    MOV P0,240
    ; Pxl-On at (P2,P1)
    MOV VX,P2
    MOV VY,P1
    MOV P0,P0
    SWRITE P0
    ; Pxl-On
    ; Load X into P0
    MOV P0,[0x2002]
    MOV P1,1
    ADD P0,P1
    ; Load Y into P1
    MOV P1,[0x2000]
    MOV P2,244
    ; Pxl-On at (P0,P1)
    MOV VX,P0
    MOV VY,P1
    MOV P0,P2
    SWRITE P0
    ; Pxl-On
    ; Load X into P2
    MOV P2,[0x2002]
    MOV P1,2
    ADD P2,P1
    ; Load Y into P1
    MOV P1,[0x2000]
    MOV P0,248
    ; Pxl-On at (P2,P1)
    MOV VX,P2
    MOV VY,P1
    MOV P0,P0
    SWRITE P0
    ; Pxl-On
    ; Load X into P0
    MOV P0,[0x2002]
    MOV P1,3
    ADD P0,P1
    ; Load Y into P1
    MOV P1,[0x2000]
    MOV P2,252
    ; Pxl-On at (P0,P1)
    MOV VX,P0
    MOV VY,P1
    MOV P0,P2
    SWRITE P0
    ; Pause - wait for key press
pause_loop:
    KEYSTAT P0
    CMP P0,0
    JZ pause_loop
    KEYIN P0

; Program end - infinite loop to keep display visible
halt:
JMP halt

ORG 0x8000

; String concatenation subroutine
str_concat:
    ; P1 = left string address
    ; Top of stack = right string address
    ; Returns result address in P0
    POP P2
    POP P3
    PUSH P2
    
    ; Allocate space for result string
    MOV P0,0x6000
    MOV P4,P0
    
    ; Copy left string
str_cat_copy_left:
    MOV P5,[P1]
    CMP P5,0
    JZ str_cat_copy_right
    MOV [P4],P5
    INC P1
    INC P4
    JMP str_cat_copy_left
    
str_cat_copy_right:
    MOV P5,[P3]
    CMP P5,0
    JZ str_cat_done
    MOV [P4],P5
    INC P3
    INC P4
    JMP str_cat_copy_right
    
str_cat_done:
    MOV [P4],0
    RET